import copy
out=copy.deepcopy(a)
R,C=len(a),len(a[0])
for r,row in enumerate(a):
    z=[j for j,v in enumerate(row) if v==0]
    if len(z)>=2:
        for c in range(min(z)+1,max(z)):
            if out[r][c]==9: out[r][c]=3
for c in range(C):
    z=[r for r in range(R) if a[r][c]==0]
    if len(z)>=2:
        for r in range(min(z)+1,max(z)):
            if out[r][c]==9: out[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in out))
